# You are given an integer array nums consisting of n elements, and an integer k.
# Find a contiguous subarray whose length is equal to k that has the maximum
# average value and return this value. Any answer with a calculation error less 
# than 10^-5 will be accepted.

# Example 1:
# Input: nums = [1,12,-5,-6,50,3], k = 4
# Output: 12.75000
# Explanation: Maximum average is (12 - 5 - 6 + 50) / 4 = 51 / 4 = 12.75

# Example 2:
# Input: nums = [5], k = 1
# Output: 5.00000
 

# Constraints:
# n == nums.length
# 1 <= k <= n <= 10^5
# -10^4 <= nums[i] <= 10^4

def findMaxAverage(nums, k):
    # extract the length of the numbers list
    num_list_length = len(nums)
    # set the max average to the lowest possible floating value according to the constraint
    max_average = -(10.00000**4)
    # set a new max average value
    new_max_average = 0.00000
    # calculate the new max average for 0-th index all the way up to k-th index, but not including k
    for i in range(k):
        new_max_average += nums[i]
    # get the NEW max average
    new_max_average /= k
    # if the OLD max average is less than the NEW max average, then update the OLD max average to the NEW max average
    if max_average < new_max_average:
        max_average = new_max_average
    # our next ending index is the k-th index
    i = k
    # our prior starting index is the 0-th index
    j = 0
    # now, find the NEW max average for all other index position by
    # 1.) multiplying by k,
    # 2.) subtracting the prior starting index number value,
    # 3.) adding the next end index number value,
    # 4.) and dividing by k
    # keep iterating until we reach the end of the list
    while i < num_list_length:
        # multiply the new max average by k
        new_max_average *= k
        # subtract the prior starting index number value from the new max average
        new_max_average -= nums[j]
        # add the next ending index number value to the new max average
        new_max_average += nums[i]
        # get the NEW max average
        new_max_average /= k
        # if the OLD max average is less than the NEW max average, then update the OLD max average to the NEW max average
        if max_average < new_max_average:
            max_average = new_max_average
        # increment the prior starting and next ending index
        i += 1
        j += 1
    # return the max average
    return round(max_average, 5)

nums = [1,12,-5,-6,50,3]
k = 4
print("Number List: ", nums, "----- k: ", k)
print("Max Average: ", findMaxAverage(nums, k), "Expected: 12.75000\n")

nums = [5]
k = 1
print("Number List: ", nums, "----- k: ", k)
print("Max Average: ", findMaxAverage(nums, k), "Expected: 5.00000\n")

nums = [-1]
k = 1
print("Number List: ", nums, "----- k: ", k)
print("Max Average: ", findMaxAverage(nums, k), "Expected: -1.00000\n")

